import{_ as o,C as i,o as e,c as s,a2 as a,b as d,w as n,a as l,E as c,a3 as u}from"./chunks/framework.DGp-bpT-.js";const A=JSON.parse('{"title":"Introduction to SREBot — AI SRE Copilot for Kubernetes","description":"SREBot documentation: AI bot for automated incident root cause analysis in Kubernetes. Integrates with Telegram, Slack, Discord, Time, Prometheus, Elasticsearch.","frontmatter":{"title":"Introduction to SREBot — AI SRE Copilot for Kubernetes","description":"SREBot documentation: AI bot for automated incident root cause analysis in Kubernetes. Integrates with Telegram, Slack, Discord, Time, Prometheus, Elasticsearch.","head":[["link",{"rel":"canonical","href":"https://srebot.site360.tech/docs/en/guide/introduction.md"}],["link",{"rel":"alternate","hreflang":"ru","href":"https://srebot.site360.tech/docs/guide/introduction.md"}],["link",{"rel":"alternate","hreflang":"en","href":"https://srebot.site360.tech/docs/en/guide/introduction.md"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://srebot.site360.tech/docs/guide/introduction.md"}]]},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"en/guide/introduction.md","lastUpdated":1785140323000}'),h={name:"en/guide/introduction.md"};function g(m,t,p,f,b,y){const r=i("Mermaid");return e(),s("div",null,[t[1]||(t[1]=a('<h1 id="introduction-to-srebot" tabindex="-1">Introduction to SREBot <a class="header-anchor" href="#introduction-to-srebot" aria-label="Permalink to &quot;Introduction to SREBot&quot;">​</a></h1><p><strong>SREBot</strong> is an intelligent observability and monitoring platform designed to rapidly uncover the root causes of incidents (Root Cause Analysis).</p><p>It integrates directly with team chats in <strong>Telegram, Slack, Discord, and <a href="https://time-messenger.ru/" target="_blank" rel="noreferrer">Time</a></strong>. The bot is deployed privately inside your Kubernetes infrastructure. It listens to messages broadcast by Prometheus Alertmanager and securely analyzes your local metrics (Prometheus) and logs (Elasticsearch).</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2>',4)),(e(),d(u,null,{default:n(()=>[c(r,{id:"mermaid-12",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Alertmanager%0A%20%20%20%20participant%20TeamChat%20as%20Team%20Chat%0A%20%20%20%20participant%20SREBot%20as%20SREBot%20(Your%20K8s)%0A%20%20%20%20participant%20Backend%20as%20AI%20Backend%0A%0A%20%20%20%20Alertmanager-%3E%3ETeamChat%3A%20Message%20with%20active%20alerts%0A%20%20%20%20SREBot-%3E%3ETeamChat%3A%20Authenticates%20and%20reads%20messages%0A%20%20%20%20SREBot-%3E%3EBackend%3A%20Requests%20analysis%0A%20%20%20%20Backend--%3E%3ESREBot%3A%20Formatted%20RCA%20Analysis%0A%20%20%20%20SREBot--%3E%3ETeamChat%3A%20Replies%20in%20the%20incident%20thread%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<ol><li><strong>Deployment (Helm):</strong> SREBot runs in your Kubernetes namespace and connects to the selected Telegram, Slack, Discord, or Time chat.</li><li><strong>Alert Reception:</strong> Alertmanager posts its routine alert notification into the incident channel.</li><li><strong>Deduplication:</strong> The bot captures the chat payload natively. It validates the fingerprint and ignores identical follow-ups to dramatically cut noise.</li><li><strong>Investigation:</strong> Empowered with internal K8s cluster capabilities (unrestricted PromQL/ES queries), the bot initiates a secure LLM sweep.</li><li><strong>Conclusion:</strong> SREBot dispatches its final RCA report via a direct <em>reply</em> to the original Alertmanager message.</li></ol><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Automated RCA:</strong> Instant incident analysis based on metrics and logs.</li><li><strong>Interactive Follow-ups:</strong> Ability to ask the bot additional questions directly in chat (via Reply) to dive deeper into details.</li><li><strong>Secure Access:</strong> The bot reads data only from your private network perimeter.</li><li><strong>Multi-language Support:</strong> The bot can respond in Russian or English depending on settings.</li></ul><h2 id="key-benefits" tabindex="-1">Key Benefits <a class="header-anchor" href="#key-benefits" aria-label="Permalink to &quot;Key Benefits&quot;">​</a></h2><ul><li><strong>Infrastructure Security:</strong> SREBot runs entirely within your perimeter, negating the requirement for exposing databases externally through risky Ingress pathways.</li><li><strong>Lower MTTD / MTTR:</strong> The AI automates early-stage investigation routines natively.</li><li><strong>Intuitive Web Dashboard:</strong> A robust UI provides transparent auditing covering SREBot&#39;s active inference pipelines.</li></ul><h2 id="open-source" tabindex="-1">Open Source <a class="header-anchor" href="#open-source" aria-label="Permalink to &quot;Open Source&quot;">​</a></h2><p>The SREBot agent (the component deployed in your infrastructure) is <strong>fully open-source</strong> and available on GitHub:</p><p>👉 <a href="https://github.com/shadrus/srebot" target="_blank" rel="noreferrer">github.com/shadrus/srebot</a></p><p>You can independently inspect the source code, verify that no unauthorized actions take place, and build your own Docker images from source if required.</p><p>Check out the <a href="/docs/en/guide/setup">Getting Started</a> section to deploy the Helm charts.</p><h2 id="documentation-contents" tabindex="-1">Documentation Contents <a class="header-anchor" href="#documentation-contents" aria-label="Permalink to &quot;Documentation Contents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Description</th></tr></thead><tbody><tr><td><a href="/docs/en/guide/setup">Getting Started</a></td><td>Helm deployment in Kubernetes</td></tr><tr><td><a href="/docs/en/guide/dashboard">Web Dashboard</a></td><td>Bot management, incidents, billing</td></tr><tr><td><a href="/docs/en/guide/organizations">Organization Management</a></td><td>Multi-org, creation and switching</td></tr><tr><td><a href="/docs/en/guide/team-management">Team Management</a></td><td>Roles, invitations, ownership transfer</td></tr><tr><td><a href="/docs/en/guide/interaction">Communicating with Bot</a></td><td>Follow-up questions, mute/unmute</td></tr><tr><td><a href="/docs/en/guide/telegram-setup">Telegram Setup</a></td><td>BotFather, Chat ID, groups</td></tr><tr><td><a href="/docs/en/guide/slack-setup">Slack Setup</a></td><td>Socket Mode, tokens, channels</td></tr><tr><td><a href="/docs/en/guide/discord-setup">Discord Setup</a></td><td>Bot Token, permissions, channels</td></tr><tr><td><a href="/docs/en/guide/time-setup">Time Setup</a></td><td>Bot Account, token, channel ID</td></tr><tr><td><a href="/docs/en/guide/alert-formatting">Alert Formatting</a></td><td>Parsing, regex, smart parsing</td></tr><tr><td><a href="/docs/en/guide/configuration">Configuration</a></td><td>Env vars, MCP servers, ignore rules</td></tr></tbody></table>',12))])}const k=o(h,[["render",g]]);export{A as __pageData,k as default};
